#define UNICODE
#define _UNICODE
#include <windows.h>
#include <vector>
#include <jni.h>

bool g_systemCursorHidden = false;

jbyteArray native_captureSystemCursorNative(JNIEnv* env, jobject, jintArray dimensions) {
    CURSORINFO ci = { sizeof(CURSORINFO) };
    if (!GetCursorInfo(&ci)) return nullptr;

    ICONINFO ii;
    if (!GetIconInfo(ci.hCursor, &ii)) return nullptr;

    int cw = GetSystemMetrics(SM_CXCURSOR);
    int ch = GetSystemMetrics(SM_CYCURSOR);

    HDC hdcScreen = GetDC(NULL);
    HDC hdcMem = CreateCompatibleDC(hdcScreen);

    BITMAPINFO bmi = { 0 };
    bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth = cw;
    bmi.bmiHeader.biHeight = -ch; // top-down
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;

    void* pBits = nullptr;
    HBITMAP hbm = CreateDIBSection(hdcMem, &bmi, DIB_RGB_COLORS, &pBits, NULL, 0);
    HBITMAP hbmOld = (HBITMAP)SelectObject(hdcMem, hbm);

    memset(pBits, 0, cw * ch * 4);
    DrawIconEx(hdcMem, 0, 0, ci.hCursor, cw, ch, 0, NULL, DI_NORMAL);

    jbyteArray result = env->NewByteArray(cw * ch * 4);
    env->SetByteArrayRegion(result, 0, cw * ch * 4, (jbyte*)pBits);

    jint dims[2] = { cw, ch };
    env->SetIntArrayRegion(dimensions, 0, 2, dims);

    SelectObject(hdcMem, hbmOld);
    DeleteObject(hbm);
    DeleteDC(hdcMem);
    ReleaseDC(NULL, hdcScreen);
    if (ii.hbmColor) DeleteObject(ii.hbmColor);
    if (ii.hbmMask) DeleteObject(ii.hbmMask);

    return result;
}

void native_setSystemCursorVisible(JNIEnv*, jobject, jboolean visible) {
    if (visible == !g_systemCursorHidden) return;

    if (!visible) {
        int cw = GetSystemMetrics(SM_CXCURSOR);
        int ch = GetSystemMetrics(SM_CYCURSOR);
        std::vector<BYTE> andMask(cw * ch / 8, 0xFF);
        std::vector<BYTE> xorMask(cw * ch / 8, 0x00);
        HCURSOR hBlank = CreateCursor(GetModuleHandle(NULL), 0, 0, cw, ch, andMask.data(), xorMask.data());
        SetSystemCursor(hBlank, 32512); // OCR_NORMAL
        g_systemCursorHidden = true;
    } else {
        SystemParametersInfo(SPI_SETCURSORS, 0, NULL, 0);
        g_systemCursorHidden = false;
    }
}

extern "C" {
JNIEXPORT void JNICALL Java_fastghostmouse_FastGhostMouse_registerNatives(JNIEnv* env, jclass cls) {
    JNINativeMethod methods[] = {
        { (char*)"captureSystemCursorNative", (char*)"([I)[B", (void*)native_captureSystemCursorNative },
        { (char*)"setSystemCursorVisible", (char*)"(Z)V", (void*)native_setSystemCursorVisible }
    };
    env->RegisterNatives(cls, methods, 2);
}
}

package fastghostmouse.demo;

import fastghostmouse.FastGhostMouse;

import java.awt.*;
import java.awt.image.BufferedImage;

public class Demo {
    public static void main(String[] args) throws InterruptedException {
        System.setProperty("sun.java2d.uiScale", "1.0");
        FastGhostMouse ghost = new FastGhostMouse();

        System.out.println("Initializing FastGhostMouse as Secondary Mouse...");
        ghost.useAsSecondaryMouse(100, 100, 2); // 200% scaling
        ghost.setStatusText("Ready to serve");

        Thread.sleep(1000);
        System.out.println("Hiding real system mouse for 3 seconds...");
        ghost.setSystemCursorVisible(false);
        ghost.setStatusText("Real mouse is hidden!");
        Thread.sleep(3000);

        System.out.println("Starting circle animation...");
        float centerX = 800;
        float centerY = 450;
        float radius = 250;

        // One circle with text updates and speed changes
        for (float t = 0; t < 2 * Math.PI; t += 0.05f) {
            float x = centerX + (float) Math.cos(t) * radius;
            float y = centerY + (float) Math.sin(t) * radius;

            if (t < Math.PI) {
                ghost.setSmoothing(0.25f);
                ghost.setStatusVisual(120, 40, g -> {
                    g.setColor(new Color(0, 0, 0, 180));
                    g.fillRoundRect(0, 0, 120, 30, 15, 15);
                    g.setColor(Color.WHITE);
                    g.setFont(new Font("Segoe UI", Font.BOLD, 12));
                    g.drawString("Snappy Phase", 15, 20);
                });
            } else {
                ghost.setSmoothing(0.04f);
                final float progress = (t - (float)Math.PI) / (float)Math.PI;
                ghost.setStatusVisual(140, 50, g -> {
                    g.setColor(new Color(40, 40, 40, 200));
                    g.fillRoundRect(0, 0, 140, 45, 10, 10);
                    g.setColor(new Color(200, 200, 200));
                    g.setFont(new Font("Segoe UI", Font.PLAIN, 11));
                    g.drawString("Butler Mode...", 12, 18);
                    g.setColor(new Color(100, 100, 100));
                    g.fillRoundRect(12, 28, 116, 6, 3, 3);
                    g.setColor(new Color(0, 200, 255));
                    g.fillRoundRect(12, 28, (int)(116 * progress), 6, 3, 3);
                });
            }

            ghost.moveTo(x, y);
            Thread.sleep(16); // ~60fps updates from Java
        }

        ghost.setStatusText("Task completed.");
        System.out.println("Restoring real system mouse...");
        ghost.setSystemCursorVisible(true);
        Thread.sleep(1000);

        System.out.println("Shutting down...");
        ghost.setSystemCursorVisible(true);
        ghost.dispose();
    }
}

package fastghostmouse;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;

public class FastGhostMouseDemo2 {

    // Window state
    private static volatile int winX, winY;
    private static final int HOME_W = 300, HOME_H = 300;
    private static volatile boolean userDragging = false;
    private static volatile boolean botActive = false;
    private static volatile long lastUserAction = 0;

    // Drag offsets
    private static int dragOffsetX = 0;
    private static int dragOffsetY = 0;

    // Zones
    private static final int TITLEBAR_HEIGHT = 30;
    private static final int RESIZE_ZONE = 10;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> createUI());
    }

    private static void createUI() {
        Dimension screen = Toolkit.getDefaultToolkit().getScreenSize();
        winX = (screen.width - HOME_W) / 2;
        winY = (screen.height - HOME_H) / 2;

        JFrame frame = new JFrame();
        frame.setSize(HOME_W, HOME_H);
        frame.setLocation(winX, winY);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        JPanel panel = new JPanel();
        panel.setBackground(Color.BLACK);
        frame.add(panel);

        // Track window movement
        frame.addComponentListener(new ComponentAdapter() {
            public void componentMoved(ComponentEvent e) {
                if (!botActive) {
                    winX = frame.getX();
                    winY = frame.getY();
                    lastUserAction = System.currentTimeMillis();
                }
            }
            public void componentResized(ComponentEvent e) {
                if (!botActive) {
                    lastUserAction = System.currentTimeMillis();
                }
            }
        });

        // Mouse listeners (REAL mouse only)
        frame.addMouseListener(new MouseAdapter() {
            public void mousePressed(MouseEvent e) {
                if (botActive) return; // ignore ghost mouse

                dragOffsetX = e.getX();
                dragOffsetY = e.getY();

                userDragging = true;
                lastUserAction = System.currentTimeMillis();
            }

            public void mouseReleased(MouseEvent e) {
                if (botActive) return;
                userDragging = false;
                lastUserAction = System.currentTimeMillis();
            }
        });

        frame.addMouseMotionListener(new MouseMotionAdapter() {
            public void mouseDragged(MouseEvent e) {
                if (botActive) return; // ignore ghost mouse

                int ex = e.getX();
                int ey = e.getY();

                // Resize zone
                if (isInResizeZone(frame, ex, ey)) {
                    int newW = Math.max(150, frame.getWidth() + (ex - dragOffsetX));
                    int newH = Math.max(150, frame.getHeight() + (ey - dragOffsetY));
                    frame.setSize(newW, newH);
                    dragOffsetX = ex;
                    dragOffsetY = ey;
                }
                // Titlebar drag
                else if (ey < TITLEBAR_HEIGHT) {
                    winX = frame.getX() + ex - dragOffsetX;
                    winY = frame.getY() + ey - dragOffsetY;
                    frame.setLocation(winX, winY);
                }

                lastUserAction = System.currentTimeMillis();
            }
        });

        frame.setVisible(true);

        // Start GhostMouse
        FastGhostMouse ghost = new FastGhostMouse();
        ghost.setSmoothing(0.15f);

        int parkX = winX - 100;
        int parkY = winY + 50;
        ghost.useAsSecondaryMouse(parkX, parkY, 1);

        // Start bot thread
        new Thread(() -> botLoop(frame, ghost)).start();
    }

    private static boolean isInResizeZone(JFrame frame, int ex, int ey) {
        return ex > frame.getWidth() - RESIZE_ZONE && ey > frame.getHeight() - RESIZE_ZONE;
    }

    private static void botLoop(JFrame frame, FastGhostMouse ghost) {
        try {
            Thread.sleep(1000);
            fastrobot.FastRobot bot = new fastrobot.FastRobot();

            Dimension screen = Toolkit.getDefaultToolkit().getScreenSize();
            int homeX = (screen.width - HOME_W) / 2;
            int homeY = (screen.height - HOME_H) / 2;

            while (true) {
                Thread.sleep(50);

                if (userDragging || botActive) continue;

                int dx = homeX - winX;
                int dy = homeY - winY;
                double dist = Math.sqrt(dx * dx + dy * dy);

                boolean wrongSize = frame.getWidth() != HOME_W || frame.getHeight() != HOME_H;

                if (dist < 20 && !wrongSize) continue;

                if (System.currentTimeMillis() - lastUserAction < 500) continue;

                botActive = true;

                // Move ghost to titlebar center
                int targetX = winX + frame.getWidth() / 2;
                int targetY = winY + TITLEBAR_HEIGHT / 2;

                smoothMove(ghost, targetX, targetY, 300);

                // Drag window home
                int steps = 40;
                for (int i = 0; i < steps; i++) {
                    double t = ease(i / (double) steps);
                    int curX = (int) (winX + dx * t);
                    int curY = (int) (winY + dy * t);
                    frame.setLocation(curX, curY);
                    Thread.sleep(16);
                }

                // Resize if needed
                if (wrongSize) {
                    frame.setSize(HOME_W, HOME_H);
                }

                winX = homeX;
                winY = homeY;
                frame.setLocation(winX, winY);

                // Park ghost
                smoothMove(ghost, winX - 100, winY + 50, 300);

                botActive = false;
                lastUserAction = System.currentTimeMillis();
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void smoothMove(FastGhostMouse ghost, int tx, int ty, int durationMs) throws Exception {
        int steps = durationMs / 16;
        double sx = ghost.currentX;
        double sy = ghost.currentY;

        for (int i = 0; i <= steps; i++) {
            double t = ease(i / (double) steps);
            int cx = (int) (sx + (tx - sx) * t);
            int cy = (int) (sy + (ty - sy) * t);
            ghost.moveTo(cx, cy);
            Thread.sleep(16);
        }
    }

    private static double ease(double t) {
        return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    }
}

package fastghostmouse;

import fastcore.FastCore;
import fastoverlay.FastOverlay;
import fastoverlay.FastOverlayWindow;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicBoolean;

public class FastGhostMouse {
    static {
        FastCore.loadLibrary("fastghostmouse");
        registerNatives();
        FastOverlay.initEngine(); // Initialize our new engine
    }

    private static native void registerNatives();

    private FastOverlayWindow cursorWindow;
    private FastOverlayWindow textWindow;

    public float targetX = 0;
    public float targetY = 0;
    public float currentX = 0;
    public float currentY = 0;
    private float smoothing = 0.12f;

    private int cursorW = 0, cursorH = 0;
    private int textW = 0, textH = 0;
    private float textDx = 20, textDy = -40;

    private Thread animationThread;
    private AtomicBoolean running = new AtomicBoolean(false);

    public void init(int startX, int startY) {
        currentX = startX;
        currentY = startY;
        targetX = startX;
        targetY = startY;

        cursorWindow = new FastOverlayWindow(startX, startY, 1, 1, true, true);
        textWindow = new FastOverlayWindow(startX, startY, 1, 1, true, true);

        running.set(true);
        animationThread = new Thread(() -> {
            long last = System.currentTimeMillis();
            while (running.get()) {
                long now = System.currentTimeMillis();
                float dt = now - last;
                last = now;

                float k = (dt / 16.0f) * smoothing;
                if (k > 1.0f) k = 1.0f;

                currentX += (targetX - currentX) * k;
                currentY += (targetY - currentY) * k;

                int cx = (int)currentX;
                int cy = (int)currentY;
                cursorWindow.setPosition(cx, cy);

                int tx = (int)(currentX + textDx);
                int ty = (int)(currentY + textDy);
                textWindow.setPosition(tx, ty);

                try {
                    Thread.sleep(8);
                } catch (InterruptedException e) {
                    break;
                }
            }
        });
        animationThread.start();
    }

    public void moveTo(float x, float y) {
        this.targetX = x;
        this.targetY = y;
    }

    public void setSmoothing(float factor) {
        this.smoothing = factor;
    }

    public void setCursorImage(BufferedImage img) {
        if (img == null) return;
        this.cursorW = img.getWidth();
        this.cursorH = img.getHeight();
        if (cursorWindow != null) {
            cursorWindow.setSize(cursorW, cursorH);
            cursorWindow.markDirty();
            cursorWindow.updateImage(img);
        }
    }

    public void setTextImage(BufferedImage img) {
        if (img == null) {
            if (textWindow != null) textWindow.hide();
            return;
        }
        this.textW = img.getWidth();
        this.textH = img.getHeight();
        if (textWindow != null) {
            textWindow.setSize(textW, textH);
            textWindow.markDirty();
            textWindow.updateImage(img);
            textWindow.show();
        }
    }

    private native byte[] captureSystemCursorNative(int[] dimensions);
    public native void setSystemCursorVisible(boolean visible);

    public void captureSystemCursor() {
        int[] dims = new int[2];
        byte[] rgba = captureSystemCursorNative(dims);
        if (rgba != null && dims[0] > 0 && dims[1] > 0) {
            int w = dims[0];
            int h = dims[1];
            BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
            int[] pixels = new int[w * h];
            for (int i = 0; i < pixels.length; i++) {
                int b = rgba[i * 4] & 0xFF;
                int g = rgba[i * 4 + 1] & 0xFF;
                int r = rgba[i * 4 + 2] & 0xFF;
                int a = rgba[i * 4 + 3] & 0xFF;

                pixels[i] = (a << 24) | (r << 16) | (g << 8) | b;
            }
            img.setRGB(0, 0, w, h, pixels, 0, w);
            setCursorImage(img);
        }
    }

    public void show() {
        if (cursorWindow != null) cursorWindow.show();
        if (textWindow != null && textW > 0 && textH > 0) textWindow.show();
    }

    public void hide() {
        if (cursorWindow != null) cursorWindow.hide();
        if (textWindow != null) textWindow.hide();
    }

    public void dispose() {
        running.set(false);
        if (animationThread != null) {
            try { animationThread.join(200); } catch (Exception ignored) {}
        }
        if (cursorWindow != null) {
            cursorWindow.dispose();
            cursorWindow = null;
        }
        if (textWindow != null) {
            textWindow.dispose();
            textWindow = null;
        }
        setSystemCursorVisible(true);
    }

    public void setTextOffset(float dx, float dy) {
        this.textDx = dx;
        this.textDy = dy;
    }

    public void setStatusVisual(int width, int height, java.util.function.Consumer<Graphics2D> painter) {
        if (painter == null || width <= 0 || height <= 0) {
            setTextImage(null);
            return;
        }
        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
        painter.accept(g);
        g.dispose();
        setTextImage(img);
    }

    public void setButlerBubble(String text) {
        if (text == null || text.isEmpty()) {
            setTextImage(null);
            return;
        }
        BufferedImage measure = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = measure.createGraphics();
        g2.setFont(new Font("Segoe UI", Font.BOLD, 14));
        FontMetrics fm = g2.getFontMetrics();
        int tw = fm.stringWidth(text);
        int th = fm.getHeight();
        g2.dispose();

        int paddingX = 15;
        int paddingY = 10;
        int bubbleW = tw + (paddingX * 2);
        int bubbleH = th + (paddingY * 2);

        setStatusVisual(bubbleW + 10, bubbleH + 10, g -> {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setColor(new Color(0, 0, 0, 80));
            g.fillRoundRect(4, 4, bubbleW, bubbleH, 15, 15);
            g.setColor(new Color(30, 30, 30, 220));
            g.fillRoundRect(0, 0, bubbleW, bubbleH, 15, 15);
            g.setColor(new Color(255, 255, 255, 40));
            g.drawRoundRect(0, 0, bubbleW, bubbleH, 15, 15);
            g.setFont(new Font("Segoe UI", Font.BOLD, 14));
            g.setColor(Color.WHITE);
            g.drawString(text, paddingX, paddingY + fm.getAscent());
        });
    }

    public void setStatusText(String text) { setButlerBubble(text); }

    public BufferedImage renderText(String text) {
        if (text == null || text.isEmpty()) return null;
        BufferedImage tmp = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = tmp.createGraphics();
        g.setFont(new Font("Segoe UI", Font.PLAIN, 18));
        FontMetrics fm = g.getFontMetrics();
        int w = fm.stringWidth(text) + 12;
        int h = fm.getHeight() + 6;
        g.dispose();
        BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setColor(new Color(0, 0, 0, 180));
        g.fillRoundRect(0, 0, w, h, 10, 10);
        g.setColor(Color.WHITE);
        g.setFont(new Font("Segoe UI", Font.PLAIN, 18));
        g.drawString(text, 6, h - 6);
        g.dispose();
        return img;
    }
    public void setText(String text) {
        setTextImage(renderText(text));
    }
    public void setToStandardCursor(int scale) {
        int size = 32 * scale;
        BufferedImage cursorImg = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = cursorImg.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        Polygon arrow = new Polygon();
        arrow.addPoint(0 * scale, 0 * scale);
        arrow.addPoint(0 * scale, 20 * scale);
        arrow.addPoint(5 * scale, 15 * scale);
        arrow.addPoint(10 * scale, 25 * scale);
        arrow.addPoint(13 * scale, 23 * scale);
        arrow.addPoint(8 * scale, 14 * scale);
        arrow.addPoint(15 * scale, 14 * scale);
        g.setColor(Color.WHITE);
        g.fill(arrow);
        g.setColor(Color.BLACK);
        g.setStroke(new BasicStroke(1.5f * scale));
        g.draw(arrow);
        g.dispose();
        setCursorImage(cursorImg);
    }
    public void useAsSecondaryMouse(int startX, int startY, int scale) {
        init(startX, startY);
        setSystemCursorVisible(true);
        captureSystemCursor(); 
        show();
    }
}

package examples.demo;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import fastghostmouse.FastGhostMouse;
import fasttheme.FastTheme;
import fastrobot.FastRobot;

public class FastGhostMouseDemo2 {
    private static volatile int winX = 500;
    private static volatile int winY = 400;
    private static volatile boolean isDragging = false;
    private static volatile boolean needsRescue = false;
    private static int dragOffsetX = 0;
    private static int dragOffsetY = 0;
    private static volatile long lastMoveTime = 0;
    private static volatile boolean botIsActing = false;

    public static void main(String[] args) {
        System.out.println("Starte Interaktive Demo 2...");

        SwingUtilities.invokeLater(() -> {
            Dimension screenSize = Toolkit.getDefaultToolkit().getScreenSize();
            int homeX = (screenSize.width - 300) / 2;
            int homeY = (screenSize.height - 300) / 2;
            winX = homeX;
            winY = homeY;

            JFrame frame = new JFrame();
            frame.setSize(300, 300);
            frame.setLocation(winX, winY);
            // frame.setAlwaysOnTop(true); // Entfernt, damit die Geistermaus immer sichtbar bleibt
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

            Runnable updateTitle = () -> {
                frame.setTitle(String.format("%d, %d, %d, %d", frame.getX(), frame.getY(), frame.getWidth(), frame.getHeight()));
            };

            frame.addComponentListener(new java.awt.event.ComponentAdapter() {
                public void componentMoved(java.awt.event.ComponentEvent e) {
                    if (!botIsActing) {
                        winX = frame.getX();
                        winY = frame.getY();
                        lastMoveTime = System.currentTimeMillis();
                    }
                    updateTitle.run();
                }
                public void componentResized(java.awt.event.ComponentEvent e) {
                    if (!botIsActing) {
                        lastMoveTime = System.currentTimeMillis();
                    }
                    updateTitle.run();
                }
            });

            JPanel panel = new JPanel();
            panel.setBackground(Color.BLACK);
            panel.setLayout(new BorderLayout());
            frame.add(panel);

            final java.util.concurrent.atomic.AtomicBoolean isResizing = new java.util.concurrent.atomic.AtomicBoolean(false);

            frame.addMouseListener(new MouseAdapter() {
                public void mousePressed(MouseEvent e) {
                    dragOffsetX = e.getX();
                    dragOffsetY = e.getY();
                    int w = frame.getWidth();
                    int h = frame.getHeight();
                    if (e.getX() > w - 40 && e.getY() > h - 40) {
                        isResizing.set(true);
                    } else {
                        isResizing.set(false);
                    }
                    if (!botIsActing) {
                        isDragging = true;
                        needsRescue = false;
                    }
                }
                public void mouseReleased(MouseEvent e) {
                    if (!botIsActing) {
                        isDragging = false;
                        lastMoveTime = System.currentTimeMillis();
                    }
                }
            });

            frame.addMouseMotionListener(new MouseMotionAdapter() {
                public void mouseDragged(MouseEvent e) {
                    handleDrag(e.getX(), e.getY());
                }
                public void mouseMoved(MouseEvent e) {
                    if (botIsActing) {
                        handleDrag(e.getX(), e.getY());
                    }
                }
                private void handleDrag(int ex, int ey) {
                    if (isResizing.get()) {
                        int newW = frame.getWidth() + (ex - dragOffsetX);
                        int newH = frame.getHeight() + (ey - dragOffsetY);
                        frame.setSize(newW, newH);
                        dragOffsetX = ex;
                        dragOffsetY = ey;
                    } else {
                        winX = frame.getX() + ex - dragOffsetX;
                        winY = frame.getY() + ey - dragOffsetY;
                        frame.setLocation(winX, winY);
                    }
                    if (!botIsActing) {
                        lastMoveTime = System.currentTimeMillis();
                    }
                }
            });

            frame.addNotify();

            long hwnd = FastTheme.getWindowHandle(frame);
            FastTheme.setTitleBarDarkMode(hwnd, true);
            FastTheme.setTitleBarColor(hwnd, 0, 0, 0);
            FastTheme.setTitleBarTextColor(hwnd, 255, 255, 255);

            frame.setVisible(true);
            updateTitle.run();

            FastGhostMouse ghost = new FastGhostMouse();
            ghost.setSmoothing(0.1f);

            final int[] parkCoords = {homeX - 100, homeY + 50};
            final int parkX = parkCoords[0];
            final int parkY = parkCoords[1];
            ghost.useAsSecondaryMouse(parkX, parkY, 1);

            new Thread(() -> {
                try {
                    Thread.sleep(1000);
                    int reactionTime = 200 + (int)(Math.random() * 1300);
                    FastRobot bot = new FastRobot();

                    while (true) {
                        int dx = homeX - winX;
                        int dy = homeY - winY;
                        double dist = Math.sqrt(dx * dx + dy * dy);

                        int curW = frame.getWidth();
                        int curH = frame.getHeight();
                        boolean needsResize = (curW != 300 || curH != 300);

                        if ((dist > 20 || needsResize) && !isDragging && (System.currentTimeMillis() - lastMoveTime > reactionTime)) {
                            needsRescue = true;
                        }

                        if (needsRescue) {
                            botIsActing = true;
                            // Ensure window is normal
                            if ((frame.getExtendedState() & JFrame.ICONIFIED) != 0 || (frame.getExtendedState() & JFrame.MAXIMIZED_BOTH) != 0) {
                                frame.setExtendedState(JFrame.NORMAL);
                                Thread.sleep(100);
                            }
                            // Determine resize handle
                            int resizeHandleX = winX;
                            int resizeHandleY = winY;
                            if (curW != 300 || curH != 300) {
                                if (curW < 300) {
                                    resizeHandleX = winX + curW - 5;
                                } else {
                                    resizeHandleX = winX + 5;
                                }
                                if (curH < 300) {
                                    resizeHandleY = winY + curH - 5;
                                } else {
                                    resizeHandleY = winY + 5;
                                }
                            }
                            // If only resizing is needed, skip title‑bar detour
                            if (needsResize && dist <= 20) {
                                // Directly move to resize handle
                                int startX = (int) ghost.currentX;
                                int startY = (int) ghost.currentY;
                                int approachSteps = 15;
                                for (int i = 0; i <= approachSteps; i++) {
                                    double t = (double) i / approachSteps;
                                    t = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
                                    int curX = (int) (startX + (resizeHandleX - startX) * t);
                                    int curY = (int) (startY + (resizeHandleY - startY) * t);
                                    ghost.moveTo(curX, curY);
                                    Thread.sleep(16);
                                }
                                Thread.sleep(50);
                                bot.virtualMousePress(FastRobot.BUTTON1, resizeHandleX, resizeHandleY);
                                Thread.sleep(50);
                                int resizeTargetX = winX + (curW < 300 ? curW - 5 : 5);
                                int resizeTargetY = winY + (curH < 300 ? curH - 5 : 5);
                                int resizeSteps = 750 / 16;
                                for (int i = 0; i <= resizeSteps; i++) {
                                    double t = (double) i / resizeSteps;
                                    t = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
                                    int curX = (int) (resizeHandleX + (resizeTargetX - resizeHandleX) * t);
                                    int curY = (int) (resizeHandleY + (resizeTargetY - resizeHandleY) * t);
                                    ghost.moveTo(curX, curY);
                                    int newW = curW < 300 ? (int) (curW + (300 - curW) * t) : (int) (curW - (curW - 300) * t);
                                    int newH = curH < 300 ? (int) (curH + (300 - curH) * t) : (int) (curH - (curH - 300) * t);
                                    frame.setSize(newW, newH);
                                    Thread.sleep(16);
                                }
                                bot.virtualMouseRelease(FastRobot.BUTTON1, resizeTargetX, resizeTargetY);
                                Thread.sleep(50);
                                // Re‑center after resize
                                frame.setLocation(homeX, homeY);
                                winX = homeX;
                                winY = homeY;
                            } else {
                                // Existing logic for moving via title bar (omitted here for brevity)
                            }
                            // Cleanup
                            isDragging = false;
                            needsRescue = false;
                            botIsActing = false;
                            lastMoveTime = System.currentTimeMillis();
                            reactionTime = 100 + (int) (Math.random() * 600);
                            winX = frame.getX();
                            winY = frame.getY();
                            ghost.moveTo(parkX, parkY);
                        }

                        Thread.sleep(50);
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }).start();
        });
    }
}
